### Bot Script

```python
class RecommendationBot:
    def __init__(self):
        # Sample data: Dictionaries to store recommendations
        self.books = {
            "Fantasy": ["The Lord of the Rings", "Harry Potter", "The Hobbit"],
            "Science Fiction": ["Dune", "Foundation", "Neuromancer"],
            "Mystery": ["The Girl with the Dragon Tattoo", "Gone Girl", "The Hound of the Baskervilles"]
        }

        self.movies = {
            "Action": ["Die Hard", "The Matrix", "Inception"],
            "Comedy": ["The Hangover", "Bridesmaids", "Superbad"],
            "Drama": ["Schindler's List", "The Godfather", "Good Will Hunting"]
        }

        self.entertainment = {
            "Music": ["The Beatles", "Bob Dylan", "Queen"],
            "Video Games": ["The Legend of Zelda", "Red Dead Redemption", "Halo"]
        }

    def recommend_books(self, genre):
        if genre in self.books:
            return self.books[genre]
        else:
            return "No recommendations available for that genre."

    def recommend_movies(self, genre):
        if genre in self.movies:
            return self.movies[genre]
        else:
            return "No recommendations available for that genre."

    def recommend_entertainment(self, category):
        if category in self.entertainment:
            return self.entertainment[category]
        else:
            return "No recommendations available for that category."

    def get_recommendations(self, user_input):
        if "book" in user_input:
            genre = user_input.split(" ")[-1]
            return self.recommend_books(genre)
        elif "movie" in user_input:
            genre = user_input.split(" ")[-1]
            return self.recommend_movies(genre)
        elif "entertainment" in user_input:
            category = user_input.split(" ")[-1]
            return self.recommend_entertainment(category)
        else:
            return "I'm not sure what you're asking for. Please specify if you want book, movie, or entertainment recommendations."

def main():
    bot = RecommendationBot()
    print("Welcome to the Recommendation Bot! Type 'exit' to quit.")

    while True:
        user_input = input("What kind of recommendation would you like? (e.g., 'book fantasy', 'movie action', 'entertainment music'): ")
        if user_input.lower() == 'exit':
            print("Goodbye!")
            break
        recommendation = bot.get_recommendations(user_input)
        print(recommendation)

if __name__ == "__main__":
    main()
```

### How It Works
1. **Initialization**: The bot initializes with sample data for books, movies, and entertainment products.
2. **Recommendation Functions**: Functions to recommend books, movies, and entertainment based on the genre or category.
3. **User Input Handling**: The bot takes user input and processes it to determine which type of recommendation is requested.
4. **Main Loop**: A loop that continuously prompts the user for input until they type 'exit'.

